2167		t, ok := e.amountTotalsShadowLocked(quoteSym, quote, base)
2168		if !ok {
2169			return nil, false
2170		}
2171	
2172		// 在 base 之上叠加本计划已选出的撤单，逐步试算后续状态。
2173		sim := make(map[int64]bool, len(base))
2174		for id := range base {
2175			sim[id] = true
2176		}
2177	
2178		var steps []amtCancelStep
2179	
2180		if t.holding > e.amtLimit {
2181			// 仅持仓金额已超限：撤掉全部剩余买单，不自动卖出。
2182			for _, id := range e.activeBuyIDsShadowLocked(sim) {
