2184				sim[id] = true
2185				// 撤单只减不增，重算必然可表示；快照供下一步记录固化。
2186				t, _ = e.amountTotalsShadowLocked(quoteSym, quote, sim)
2187			}
2188			return steps, true
2189		}
2190	
2191		for t.total > e.amtLimit {
2192			ids := e.activeBuyIDsShadowLocked(sim)
2193			if len(ids) == 0 {
2194				break // 兜底：无单可撤
2195			}
2196			id := ids[0] // 编号最大者先撤
2197			steps = append(steps, amtCancelStep{id: id, totals: t})
2198			sim[id] = true
2199			t, ok = e.amountTotalsShadowLocked(quoteSym, quote, sim)
2200			if !ok {
2201				return nil, false
2202			}
2203		}
2204		return steps, true
2205	}
