2226					e.amtLimit, cause, step.totals.holding)
2227			} else {
2228				reason = fmt.Sprintf("账户总持仓金额上限 %d：%s后持仓金额 %d 与买单剩余占用 %d 合计 %d 超限，按订单编号从大到小撤销买单全部剩余量",
2229					e.amtLimit, cause, step.totals.holding, step.totals.reserved, step.totals.total)
2230			}
2231			e.cancelAmountLocked(o, reason, step.totals)
2232			canceled = append(canceled, step.id)
2233		}
2234		return canceled
2235	}
